def find_all_maximal_rectangles(grid):
    """Find all maximal uniform rectangles using proper extension checking."""
    m, n = len(grid), len(grid[0])
    maximal = []

    for r_start in range(m):
        for c_start in range(n):
            val = grid[r_start][c_start]

            # Expand right
            c_end = c_start
            while c_end < n - 1 and grid[r_start][c_end+1] == val:
                c_end += 1

            if c_end == c_start:
                continue

            # Expand down
            r_end = r_start
            while r_end < m - 1:
                all_match = True
                for c in range(c_start, c_end + 1):
                    if grid[r_end+1][c] != val:
                        all_match = False
                        break
                if not all_match:
                    break
                r_end += 1

            # Now try to extend this rectangle in all directions
            def can_extend(r_min, c_min, r_max, c_max):
                # Try up
                if r_min > 0:
                    return all(grid[r_min-1][c] == val for c in range(c_min, c_max+1))
                # Try down
                if r_max < m - 1:
                    return all(grid[r_max+1][c] == val for c in range(c_min, c_max+1))
                # Try left
                if c_min > 0:
                    return all(grid[r][c_min-1] == val for r in range(r_min, r_max+1))
                # Try right
                if c_max < n - 1:
                    return all(grid[r][c_max+1] == val for r in range(r_min, r_max+1))
                return False

            if not can_extend(r_start, c_start, r_end, c_end):
                maximal.append((r_start, c_start, r_end, c_end))

    return set(map(tuple, maximal))

